import React from 'react';
import styles from './search_header.module.css'

const Search_header = (props) => {
    const onClick = () => {
        console.log('onClick')
    }

    const onKeyPress = () => {
        console.log('onKeyPress')
    }

    return (
        <header className={styles.header}>
            <img className={styles.img} src="/img/youtube_logo.png" alt="logo" />
            <h1 className={styles.title}>Youtube</h1>
            <input className={styles.input} type="search" placeholder="Search..." onKeyPress={onKeyPress} />
            <button className={styles.button} onClick={onClick}>Search</button>
        </header>
    )

};

export default Search_header;
